#!/usr/bin/env node
import { buildSite, BuildOptions } from './generator';
import { startDevServer } from './server';

export function parseArgs(args: string[]): BuildOptions & { port?: number } {
  const options: BuildOptions & { port?: number } = {};
  for (let index = 0; index < args.length; index += 1) {
    const argument = args[index];
    if (argument === '--port') {
      const value = args[++index];
      const port = Number(value);
      if (!value || !Number.isInteger(port) || port < 1 || port > 65535) throw new Error('--port requires a valid port');
      options.port = port;
    } else if (argument === '--content' || argument === '--output' || argument === '--templates') {
      const value = args[++index];
      if (!value) throw new Error(`${argument} requires a directory`);
      if (argument === '--content') options.contentDir = value;
      else if (argument === '--output') options.outputDir = value;
      else options.templatesDir = value;
    }
  }
  return options;
}

if (require.main === module) {
  const [command, ...args] = process.argv.slice(2);
  if (command !== 'build' && command !== 'serve') {
    console.error('Usage: ssg build [--content <dir>] [--output <dir>] [--templates <dir>] | ssg serve [--content <dir>] [--output <dir>] [--templates <dir>] [--port <port>]');
    process.exitCode = 1;
  } else {
    try {
      if (command === 'serve') {
        startDevServer(parseArgs(args)).then(() => console.log(`SSG dev server running at http://localhost:${parseArgs(args).port ?? 3000}`)).catch((error) => {
          console.error(error instanceof Error ? error.message : error);
          process.exitCode = 1;
        });
        return;
      }
      const pages = buildSite(parseArgs(args));
      console.log(`Generated ${pages.length} page${pages.length === 1 ? '' : 's'} .`);
    } catch (error) {
      console.error(error instanceof Error ? error.message : error);
      process.exitCode = 1;
    }
  }
}

